using System.Text.Json;
using System.Text.Json.Serialization.Metadata;

// Set up options with the default reflection-based resolver
var options = new JsonSerializerOptions
{
    TypeInfoResolver = new DefaultJsonTypeInfoResolver(),
    WriteIndented = true
};

// 1) Strongly-typed retrieval: GetTypeInfo<T>() returns JsonTypeInfo<T> directly
JsonTypeInfo<Person> personInfo = options.GetTypeInfo<Person>();
Console.WriteLine($"Got typed metadata for: {personInfo.Type.Name}");

string json = JsonSerializer.Serialize(new Person("Alice", 30), personInfo);
Console.WriteLine(json);

// 2) Probe without throwing: TryGetTypeInfo returns false if unavailable
if (options.TryGetTypeInfo(typeof(Person), out JsonTypeInfo? info))
{
    Console.WriteLine($"\nTryGetTypeInfo succeeded for Person (kind: {info!.Kind})");
}

// Now demonstrate the "not available" case using an empty resolver
var restrictedOptions = new JsonSerializerOptions
{
    TypeInfoResolver = JsonTypeInfoResolver.Combine() // resolves nothing
};

if (restrictedOptions.TryGetTypeInfo(typeof(Person), out _))
{
    Console.WriteLine("Unexpected: metadata found");
}
else
{
    Console.WriteLine("\nTryGetTypeInfo correctly returned false — no metadata for Person.");
}

record Person(string Name, int Age);

